// Devuelve el item del llamador con la configuracion adjunta en _config (clave -> valor).
// F5-01/F5-02/F5-03/F5-04: fuente unica de verdad = Data Table Configuracion_CCB.
const get = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const base = get('When Executed by Another Workflow');
const _config = Object.fromEntries($('Data Table - Leer configuración').all().map(i => [i.json.clave, i.json.valor]));
return { json: { ...base, _config } };

